// Helper function to calculate the sum of odd integers at even indices
function SumOddAtEvenPositions(lst: seq<int>): int
    requires |lst| > 0
{
    var sum := 0;
    var i := 0;
    while i < |lst|
        invariant 0 <= i <= |lst|
        invariant sum == SumOddAtEvenIndices(lst, i)
    {
        if i % 2 == 0 && lst[i] % 2 != 0 {
            sum := sum + lst[i];
        }
        i := i + 1;
    }
    return sum;
}

function SumOddAtEvenIndices(lst: seq<int>, upTo: int): int
    requires |lst| > 0 && upTo <= |lst|
{
    var sum := 0;
    var j := 0;
    while j < upTo
        invariant 0 <= j <= upTo
        invariant sum == SumOddAtEven(lst, j)
    {
        if j % 2 == 0 && lst[j] % 2 != 0 {
            sum := sum + lst[j];
        }
        j := j + 1;
    }
    return sum;
}

function SumOddAtEven(lst: seq<int>, upTo: int): int
    requires |lst| > 0 && upTo <= |lst|
{
    var sum := 0;
    for i := 0 to upTo - 1
        if i % 2 == 0 && lst[i] % 2 != 0 {
            sum := sum + lst[i];
        }
    return sum;
}

